local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local KTool = CS.Engine.Lib.KTool
local TimeSpan = CS.System.TimeSpan
local gameUtils = CS.GameUtils

------------ import ------------
------------ import ------------

------------ define ------------

local settingMgr = SettingMgr:GetInstance()

local INDEX_MAX = 5
local TaskPrefabName = 'TrailTaskCellNode'
local TrailTaskCellNodeLuaPath = 'Game.UI.TrailStage.TrailTaskCellNode'

---@type TrailBattleMgr
local TrailBattleMgr = import('Game.TrailBattle.TrailBattleMgr')

------------ define ------------

---@class TrailTaskDialog
---@field EmptyText                        UnityEngine.RectTransform
---@field ListView                        SuperScrollView.LoopListView2 @列表
---@field TimerText                        UnityEngine.UI.Extensions.TextPic
---@field NameText                        UnityEngine.UI.Text @名称描述
local TrailTaskDialog = Class("TrailTaskDialog")

function TrailTaskDialog:__init()
    self.isAnimationPlayed = false
    self.data = nil
    self.serverData = nil
end

function TrailTaskDialog:__delete()
    self.controller = nil
    self.isAnimationPlayed = nil
    self.data = nil
    self.serverData = nil
end

function TrailTaskDialog:Awake()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComponent then
        local trialRemainTime = checkInt(playerComponent.playerDojo.trialRemainTime)
        self.TimerText.text = string.format('%s%s', localize('剩余'), CfUtils.GetTimeHumanize(trialRemainTime))
    end
    self.ListView:InitListView(0, Bind(self, self.OnGetItemByIndex))
end

function TrailTaskDialog:FilterData()
    local setting = settingMgr:GetSetting(AutoIds.IdSetting743, "TrailTaskVo")
    local t = setting:GetAll()
    self.data = {}
    local trailBattleMgr = TrailBattleMgr:GetInstance()
    local mySegment = checkNumber(trailBattleMgr:GetMySegment())
    for _, v in pairs(t) do
        if checkInt(v.taskBelong) == 0 or checkInt(v.taskBelong) == mySegment then
            local preTaskId = checkInt(v.before)
            if  preTaskId > 0 then
                ---存在前置任务
                local needInsert = 0
                local preDojo = self:GetTrailTaskById(preTaskId)
                if preDojo then
                    if checkInt(preDojo.status) == 2 then
                        ---已领取的情况下
                        needInsert = 1
                    end
                else
                    needInsert = 1
                end
                if needInsert == 1 then
                    table.insert(self.data, v)
                end
            else
                table.insert(self.data, v)
            end
        end
    end
end

---FreshListView
---日常任务与周长任务刷新列表listview数据
function TrailTaskDialog:FreshListView()
    self:FilterData()
    if self.data then
        local len = table.count(self.data)
        self.data = self:SortTrailTasks(self.data)
        GameUtils.ReloadData(self.ListView, len)
    end
end

function TrailTaskDialog:GetTrailTaskById(id)
    if self.serverData then
        for i, v in pairs(self.serverData) do
            if checkNumber(v.id) == checkNumber(id) then
                return v
            end
        end
    end
end

function TrailTaskDialog:SortTrailTasks(data)
    local list0 = {}
    local list1 = {}
    local list2 = {}
    for i, v in pairs(data) do
        local dojo = self:GetTrailTaskById(v.taskId)
        if not isNull(dojo) then
            if checkNumber(dojo.status) == 0 then
                table.insert(list0, v)
            elseif checkNumber(dojo.status) == 1 then
                ---可领取
                table.insert(list1, v)
            elseif checkNumber(dojo.status) == 2 then
                ---已领取
                table.insert(list2, v)
            end
        else
            table.insert(list0, v)
        end
    end
    for i, v in pairs(list0) do
        table.insert(list1, v)
    end
    for i, v in pairs(list2) do
        table.insert(list1, v)
    end
    return list1
end

---OnGetItemByIndex
---邮箱列表cell生成函数
---@param listView SuperScrollView.LoopListView2
---@param index number 位置
function TrailTaskDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return
    end
    local position = (index + 1)
    local vo = self.data[position]
    if isNull(vo) then
        return nil
    end
    local cell = listView:NewListViewItem(TaskPrefabName)
    ---@type Engine.Modules.LuaBehaviour
    local luaMB = GetLuaBehaviour(cell.gameObject, TrailTaskCellNodeLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        luaMB:Init()
    end
    if not KTool.IsNull(luaMB) and not KTool.IsNull(luaMB.Env) then
        local dojo = self:GetTrailTaskById(vo.taskId)
        luaMB.Env:FreshNode(vo, dojo, function()
            self:Request()
        end)

        if self.isAnimationPlayed then
            luaMB.Env:FixNormalSetting()
        else
            ---未播放过
            if position <= INDEX_MAX then
                luaMB.Env:PlayAnimation2(position, true)
                if position == INDEX_MAX then
                    self.isAnimationPlayed = true
                end
            else
                luaMB.Env:FixNormalSetting()
            end
        end
    end
    return cell
end

function TrailTaskDialog:Request()
    GameUtils.Request(Interfaces.TrailTask, {}, function(request, response)
        if checkInt(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            self.serverData = checkTable(responseData.taskInfo)
            self:FreshListView()
            GameUtils.SetRedPointNum(Constants.RedPointConst.TrailQuestTask, self:GetTaskCanDrawNum(self.serverData))
        end
    end)
end

--获取可领取任务数量
function TrailTaskDialog:GetTaskCanDrawNum(taskData)
    local num = 0
    if not taskData then
        return num
    end

    for k, v in pairs(taskData) do
        if checkNumber(v.status) == 1 then 
            return 1
        end
    end
    return num
end

function TrailTaskDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:Request()
    end))
    return coWait
end

function TrailTaskDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return TrailTaskDialog